package com.wakemyway.app.voice

/**
 * Pilot evidence boundary: text generated by the model is not audible speech.
 * Only a listener's explicit confirmation can unlock an audio-quality rating.
 */
internal object GptLiveAudibilityGate {
    fun canReport(previewConnected: Boolean, sessionClosed: Boolean): Boolean =
        previewConnected && sessionClosed

    fun canRate(
        previewConnected: Boolean,
        sessionClosed: Boolean,
        userConfirmedAudible: Boolean,
    ): Boolean = canReport(previewConnected, sessionClosed) && userConfirmedAudible
}
